def min_sum():
    perms = list(itertools.permutations(range(1, 7)))
    min_val = float('inf')
    best = None
    for b in perms:
        for c in perms:
            s = 0
            for i in range(6):
                s += (i + 1) * b[i] * c[i]
            if s < min_val:
                min_val = s
