{"operation":"run_python","code":"import math

def domino_tilings(m, n):
    prod = 1
    for j in range(1, m//2 + 1):
        for k in range(1, n//2 + 1):
            term = 4 * (math.cos(math.pi * j / (m + 1))**2 + math.cos(math.pi * k / (n + 1))**2)
            prod *= term
    return round(prod)

print(domino_tilings(8, 8))
